#include "NCLGLmanager.h"

NCLGLmanager::NCLGLmanager() {
    //wasmclglfor = (NCLGLFor*)malloc(sizeof(NCLGLFor)*10);
    currFor = 0;
}

int NCLGLmanager::addFor(int width, int height) {
    wasmclglfor[currFor] = new NCLGLFor(width, height);

    currFor++;

    return currFor-1;
}

void NCLGLmanager::destroyContext() {
    for(int n=0; n <= currFor; n++) {
        delete wasmclglfor[n]->wasmclgl;
        wasmclglfor[n]->wasmclgl = nullptr;

        delete wasmclglfor[n];
        wasmclglfor[n] = nullptr;
    }

    currFor = 0;
}

void NCLGLmanager::resetGLConf() {
    glClearColor(0.0, 0.0, 0.0, 1.0);
    glEnable(GL_DEPTH_TEST);
    glEnable(GL_CULL_FACE);
    glCullFace(GL_BACK);
    glDepthFunc(GL_LEQUAL);
    glClearDepthf(1.0);
}

void NCLGLmanager::clearContext() {
    glBindFramebuffer(GL_FRAMEBUFFER, 0);
    glViewport(0, 0, wasmclglfor[0]->wasmclgl->width, wasmclglfor[0]->wasmclgl->height);
    glClearColor(0.0, 0.0, 0.0, 1.0);
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
}

void NCLGLmanager::clearOutputFrameBuffers() {
    for(int n=0; n <= currFor; n++)
        wasmclglfor[n]->clearOutputFrameBuffers();
}

void NCLGLmanager::fillArg(int idWasmCLGLFor, char *argument, float * clearColor) {
    wasmclglfor[idWasmCLGLFor]->fillArg(argument, clearColor);
}

void NCLGLmanager::getGPUForArg(int idWasmCLGLFor, char *argument, int idWasmCLGLForShared) {
    NCLGLArgValue * argVal = wasmclglfor[idWasmCLGLForShared]->getArgBuffer(argument);

    int exists = -1;
    for(int n=0; n < wasmclglfor[idWasmCLGLFor]->argsValuesCount; n++) {
        if(strcmp(wasmclglfor[idWasmCLGLFor]->_argsValues[n].varnameC.c_str(), argument)==0) {
            exists = n;
            break;
        }
    }

    if(exists != -1) {
        wasmclglfor[idWasmCLGLFor]->_argsValues[exists] = *argVal;
    } else {
        wasmclglfor[idWasmCLGLFor]->_argsValues[wasmclglfor[idWasmCLGLFor]->argsValuesCount] = *argVal;
        wasmclglfor[idWasmCLGLFor]->argsValuesCount++;
    }
}

